import React, { Component } from 'react'
import PropTypes from 'prop-types'
import LayoutContentStyle from '../../../../../../components/utility/layoutContent'
import { Table } from 'antd'

class InsuredTable extends Component {
  static propTypes = {
    insuredData: PropTypes.array // this contains { id, name, value }
  }

  getColumnsData = (data) => {
    // handle the table data
    return [
      {
        title: 'Sr. No.',
        render: (text, record, index) => index + 1
      },
      {
        title: 'Insured Details',
        children: [
          {
            title: 'Name',
            dataIndex: 'insured_details.name',
            key: 'name'
          },
          {
            title: 'Gender',
            dataIndex: 'insured_details.gender',
            render: (text) => text === 'M' ? 'Male' : 'Female',
            key: 'gender'
          },
          {
            title: 'Dob',
            dataIndex: 'insured_details.dob',
            key: 'dob'
          },
          {
            title: 'Relation',
            dataIndex: 'insured_details.relation',
            key: 'relation'
          }
        ]
      },
      {
        title: 'Beneficiary Details',
        children: [
          {
            title: 'Name',
            dataIndex: 'beneficiary_details.name',
            key: 'name'
          },
          {
            title: 'Dob',
            dataIndex: 'beneficiary_details.dob',
            key: 'dob'
          },
          {
            title: 'Relation',
            dataIndex: 'beneficiary_details.relation',
            key: 'relation'
          }
        ]
      }
    ]
  }

  render () {
    const { insuredData } = this.props
    return (
      <LayoutContentStyle className='details-info-container policy-detail-card'>
        <div>
          <h3 className='policy-title'>Insureds</h3>
          <Table
            pagination={{
              pageSize: 100
            }}
            rowKey={data => data.id}
            bordered
            columns={this.getColumnsData()}
            dataSource={insuredData}
          />
        </div>
      </LayoutContentStyle>
    )
  }
}

export default InsuredTable
